
/**
 * Zala QI's World
 * Cinematic Scene Preparation Engine v2
 *
 * Supports HTTPS reference images and data URLs
 * generated by the Character Identity Engine.
 *
 * Uploads data URL images to FAL storage before
 * preparing a cinematic reference frame.
 */

import { fal } from '@fal-ai/client';

const SCENE_IMAGE_MODEL = 'fal-ai/flux-kontext/dev';

const ALLOWED_IMAGE_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/webp'
]);

const MAX_IMAGE_BYTES = 30 * 1024 * 1024;

function wantsStylization(description) {
  return /\b(anime|animated|animation|cartoon|pixar|claymation|stop[ -]?motion|cel[ -]?shaded|illustration|comic[ -]?book|3d[ -]?render|cgi|video[ -]?game|stylized|non[ -]?photorealistic)\b/i.test(description);
}

function normalizeFormat(format) {
  return format === 'landscape'
    ? 'landscape'
    : 'portrait';
}

async function resolveReferenceImageUrl(referenceImageUrl) {
  if (
    typeof referenceImageUrl !== 'string' ||
    !referenceImageUrl.trim()
  ) {
    throw new Error(
      'A character reference image is required.'
    );
  }

  if (/^https:\/\//i.test(referenceImageUrl)) {
    return referenceImageUrl;
  }

  const match = referenceImageUrl.match(
    /^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=\s]+)$/i
  );

  if (!match) {
    throw new Error(
      'Reference image must be an HTTPS URL or a supported image data URL.'
    );
  }

  const mimeType = match[1].toLowerCase();

  if (!ALLOWED_IMAGE_TYPES.has(mimeType)) {
    throw new Error(
      'Unsupported character reference image type.'
    );
  }

  const base64 = match[2].replace(/\s/g, '');

  const bytes = Buffer.from(base64, 'base64');

  if (
    bytes.length === 0 ||
    bytes.length > MAX_IMAGE_BYTES
  ) {
    throw new Error(
      'Character reference image is empty or exceeds 30 MB.'
    );
  }

  const extension = mimeType === 'image/jpeg'
    ? 'jpg'
    : mimeType === 'image/png'
      ? 'png'
      : 'webp';

  const file = new File(
    [bytes],
    `zala-character-reference.${extension}`,
    { type: mimeType }
  );

  const uploadedUrl = await fal.storage.upload(file);

  if (
    typeof uploadedUrl !== 'string' ||
    !/^https:\/\//i.test(uploadedUrl)
  ) {
    throw new Error(
      'Could not upload character reference image to FAL storage.'
    );
  }

  return uploadedUrl;
}

export async function prepareSceneImage({
  referenceImageUrl,
  sceneDescription,
  format = 'portrait'
}) {
  if (
    typeof sceneDescription !== 'string' ||
    !sceneDescription.trim()
  ) {
    throw new Error(
      'Scene description is missing.'
    );
  }

  const imageUrl = await resolveReferenceImageUrl(
    referenceImageUrl
  );

  const style = wantsStylization(sceneDescription)
    ? [
        'ART DIRECTION: Follow the explicitly requested visual style.',
        'Preserve coherent environments, spatial relationships,',
        'consistent character design, expressive lighting',
        'and professional cinematic framing.'
      ]
    : [
        'ART DIRECTION: Photographic live-action cinema.',
        'The result should resemble footage captured',
        'using a professional cinema camera.',
        'Maintain realistic skin texture, hair, clothing,',
        'lighting, shadows, perspective and depth.',
        'Use realistic materials and environmental details.',
        'Avoid plastic skin, cartoon features, distorted',
        'anatomy, artificial scenery and excessive smoothing.'
      ];

  const composition =
    normalizeFormat(format) === 'landscape'
      ? 'Compose a horizontal widescreen cinematic frame.'
      : 'Compose a vertical cinematic frame for mobile viewing.';

  const prompt = [
    'Transform the provided reference photograph into',
    'one coherent cinematic opening frame for a music video.',
    'Keep the same recognizable person from the photograph.',
    'Preserve facial structure, skin tone, hairstyle,',
    'hair length, body proportions and distinguishing features.',
    'Integrate the person naturally into the environment',
    'with consistent perspective, scale and lighting.',
    'SCENE DIRECTION:',
    sceneDescription.trim(),
    ...style,
    'Follow the requested location, clothing, actions',
    'and atmosphere.',
    'Do not introduce conflicting locations or props.',
    'Avoid duplicate characters, collages, text,',
    'logos, watermarks and transition overlays.',
    composition
  ].join(' ');

  const result = await fal.subscribe(
    SCENE_IMAGE_MODEL,
    {
      input: {
        image_url: imageUrl,
        prompt,
        num_images: 1,
        output_format: 'jpeg'
      },
      logs: false
    }
  );

  const preparedImageUrl =
    result?.data?.images?.[0]?.url ||
    result?.images?.[0]?.url;

  if (
    typeof preparedImageUrl !== 'string' ||
    !/^https:\/\//i.test(preparedImageUrl)
  ) {
    throw new Error(
      'Scene Preparation Engine returned no valid image URL.'
    );
  }

  return {
    imageUrl: preparedImageUrl,
    model: SCENE_IMAGE_MODEL
  };
}
